using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API for a given resource path.")]
    public static async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        ILogger<ExternalApiTool> logger,
        [Description("The API resource path to query, e.g. \"users/42\".")] string resourcePath,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching external API resource: {Path}", resourcePath);

        using var client = httpClientFactory.CreateClient("ExternalApi");

        try
        {
            using var response = await client.GetAsync(resourcePath, cancellationToken);
            response.EnsureSuccessStatusCode();

            var body = await response.Content.ReadAsStringAsync(cancellationToken);
            logger.LogInformation("Received {Length} chars from {Path}", body.Length, resourcePath);
            return body;
        }
        catch (HttpRequestException ex)
        {
            logger.LogError(ex, "API request failed for {Path}", resourcePath);
            return JsonSerializer.Serialize(new { error = ex.Message });
        }
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer;

[McpServerPromptType]
public sealed class SummarizePrompt
{
    [McpServerPrompt("summarize"), Description("Generates a prompt that asks the model to summarize the given text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional target length such as '2 sentences' or '100 words'.")] string? length = null)
    {
        var instruction = length is not null
            ? $"Summarize the following text in approximately {length}."
            : "Summarize the following text concisely.";

        return
        [
            new PromptMessage
            {
                Role = Role.User,
                Content = new Content { Type = "text", Text = $"{instruction}\n\n{text}" }
            }
        ];
    }
}

