 using System.ComponentModel;
 using System.Net.Http.Json;
 using System.Text.Json;
 using Microsoft.Extensions.Logging;
 using ModelContextProtocol.Server;

 namespace McpServer;

 [McpServerToolType]
 public sealed class ExternalApiTool
 {
     [McpServerTool(Name = "fetch_data"), Description("Fetches data from an external API for a given resource path.")]
     public static async Task<string> FetchDataAsync(
         IHttpClientFactory httpClientFactory,
         ILogger<ExternalApiTool> logger,
         [Description("The API resource path to query, e.g. \"users/42\".")] string resourcePath,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Fetching external API resource: {Path}", resourcePath);

         using var client = httpClientFactory.CreateClient("ExternalApi");

         try
         {
             using var response = await client.GetAsync(resourcePath, cancellationToken);
             response.EnsureSuccessStatusCode();

             var body = await response.Content.ReadAsStringAsync(cancellationToken);
             logger.LogInformation("Received {Length} chars from {Path}", body.Length, resourcePath);
             return body;
         }
         catch (HttpRequestException ex)
         {
             logger.LogError(ex, "API request failed for {Path}", resourcePath);
             return JsonSerializer.Serialize(new { error = ex.Message });
         }
     }
 }

